import { Request, Response, Router } from "express";
import { CreateProjectUseCase } from "../application/CreateProjectUseCase";
import { asyncHandler, bodyOf, requiredString } from "./httpSupport";

export class ProjectController {
  constructor(private readonly createProject: CreateProjectUseCase) {}

  routes(): Router {
    const router = Router();
    router.post(
      "/projects",
      asyncHandler((req, res) => this.create(req, res)),
    );
    return router;
  }

  private async create(req: Request, res: Response): Promise<void> {
    const name = requiredString(bodyOf(req), "name");
    const project = await this.createProject.execute({ name });
    res.status(201).json(project);
  }
}

